module lock_control (

```
	 input wire clk,
	 input wire reset,
	 input wire lock,
	 input wire unlock,
	 output reg unlocked
 );
	 reg unlocked_next = 1'b0;
	 always @(lock or unlock or unlocked) begin
		 if (reset == 1'b1) begin
			 unlocked_next = 1'b1; 
		 end else if (lock == 1'b1) begin
			 unlocked_next = 1'b0; 
		 end else if (unlock == 1'b1) begin
			 unlocked_next = 1'b1; 
		 end else begin
			 unlocked_next = unlocked; 
		 end
	 end
	 always @(posedge clk) begin
		 unlocked <= unlocked_next;
	 end
 endmodule
